<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Models\User;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\{DB,Event,Notification};
class PmsAccessAuditTest extends TestCase {
 use DatabaseTransactions;
 protected function setUp():void {parent::setUp();$this->seed(\App\Modules\Pms\Database\Seeders\PmsFoundationSeeder::class);Event::fake();Notification::fake();$this->withSession(['judibas_admin'=>true]);}
 private function company(string $name):array {$platform=DB::table('communication_companies')->insertGetId(['name'=>$name,'created_at'=>now(),'updated_at'=>now()]);$company=DB::table('pms_companies')->insertGetId(['name'=>$name,'platform_company_id'=>$platform,'status'=>true,'created_at'=>now(),'updated_at'=>now()]);return [$platform,$company];}
 private function department(string $name):int{return DB::table('pms_departments')->insertGetId(['dept_name'=>$name,'status'=>1,'created_at'=>now(),'updated_at'=>now()]);}
 private function project(int $company,string $name,array $departments):array {$client=$this->postJson('/pms/api/clients',['company_id'=>$company,'name'=>$name.' Client','status'=>true])->assertCreated()->json('client.id');$workflow=DB::table('pms_workflows')->where('is_default',true)->value('id');$project=$this->postJson('/pms/api/projects',['client_id'=>$client,'name'=>$name,'start_date'=>'2026-10-13','workflow_ids'=>[$workflow],'department_ids'=>$departments])->assertCreated()->json('project_id');DB::table('pms_projects')->where('id',$project)->update(['approval'=>'approved']);return [$project,$client,$workflow];}
 private function task(int $project,int $dep,int $workflow,string $title):int {$column=DB::table('pms_workflow_columns')->where('workflow_id',$workflow)->where('is_initial',true)->value('id');return $this->postJson('/pms/api/tasks',['project_id'=>$project,'department_id'=>$dep,'workflow_id'=>$workflow,'workflow_column_id'=>$column,'title'=>$title,'status'=>'pending'])->assertOk()->json('task.id');}
 private function user(int $platform,int $dep,string $roleKey,array $permissions):User {$u=User::factory()->create(['is_active'=>true,'status'=>1]);DB::table('user_product_access')->insert(['user_id'=>$u->id,'product_slug'=>'projects']);DB::table('communication_company_memberships')->insert(['user_id'=>$u->id,'company_id'=>$platform]);DB::table('pms_user_departments')->insert(['user_id'=>$u->id,'dept_id'=>$dep]);$role=DB::table('pms_roles')->insertGetId(['role_name'=>'Audit '.$roleKey.' '.$u->id,'role_key'=>$roleKey,'created_at'=>now(),'updated_at'=>now()]);DB::table('pms_role_users')->insert(['user_id'=>$u->id,'role_id'=>$role]);foreach($permissions as $key)$this->grant($u,$key);return $u;}
 private function grant(User $u,string $key):void {$role=DB::table('pms_role_users')->where('user_id',$u->id)->value('role_id');$permission=DB::table('pms_permissions')->where('permission_key',$key)->value('id');DB::table('pms_permission_roles')->insertOrIgnore(['role_id'=>$role,'permission_id'=>$permission]);}
 public function test_team_lead_sees_own_and_team_department_work_only_inside_selected_companies():void {
  [$platform,$company]=$this->company('Audit Cedar');[, $foreignCompany]=$this->company('Audit Atlas');$seo=$this->department('Audit SEO');$dev=$this->department('Audit Development');[$project,$client,$workflow]=$this->project($company,'Audit Cedar Portal',[$seo,$dev]);[$foreign,,$foreignWorkflow]=$this->project($foreignCompany,'Audit Atlas Portal',[$seo]);$team=$this->task($project,$seo,$workflow,'SEO team deliverable');$own=$this->task($project,$dev,$workflow,'My own development task');$hidden=$this->task($project,$dev,$workflow,'Other department deliverable');$outside=$this->task($foreign,$seo,$foreignWorkflow,'Foreign company SEO');
  $lead=$this->user($platform,$seo,'team_leader',['project-view','my-work-view','task-view-team','task-edit','task-status','report-view']);DB::table('pms_task_user')->insert(['task_id'=>$own,'user_id'=>$lead->id]);$this->withSession(['judibas_admin'=>false])->actingAs($lead);
  $this->getJson('/pms/api/hierarchy-board?scope=project&id='.$project)->assertOk()->assertJsonCount(2,'data.tasks')->assertJsonFragment(['title'=>'SEO team deliverable'])->assertJsonFragment(['title'=>'My own development task']);
  $this->getJson('/pms/api/my-work')->assertOk()->assertJsonFragment(['title'=>'SEO team deliverable'])->assertJsonFragment(['title'=>'My own development task'])->assertJsonMissing(['title'=>'Other department deliverable']);
  $this->getJson('/pms/api/tasks/'.$team)->assertOk();$this->postJson('/pms/api/tasks/'.$team.'/comments',['body'=>'Team review note'])->assertCreated();
  foreach([$hidden,$outside] as $id){$this->getJson('/pms/api/tasks/'.$id)->assertNotFound();$this->patchJson('/pms/api/tasks/'.$id.'/board',['title'=>'Unauthorized'])->assertNotFound();}
  $this->getJson('/pms/api/reports/data?client_id='.$client)->assertOk()->assertJsonFragment(['title'=>'SEO team deliverable'])->assertJsonMissing(['title'=>'Other department deliverable']);
  $permission=DB::table('pms_permissions')->where('permission_key','task-view-team')->value('id');$role=DB::table('pms_role_users')->where('user_id',$lead->id)->value('role_id');DB::table('pms_permission_roles')->where('role_id',$role)->where('permission_id',$permission)->delete();$this->getJson('/pms/api/tasks/'.$team)->assertNotFound();$this->getJson('/pms/api/tasks/'.$own)->assertOk();
 }
 public function test_global_manager_view_and_company_transfer_are_separate_permissions_and_transfer_preserves_history():void {
  [$platform,$company]=$this->company('Audit Harbor');[$targetPlatform,$targetCompany]=$this->company('Audit Summit');$dep=$this->department('Audit Graphic');[$project,$client,$workflow]=$this->project($company,'Audit Harbor Brand',[$dep]);[$destination,$targetClient,$targetWorkflow]=$this->project($targetCompany,'Audit Summit Brand',[$dep]);$task=$this->task($project,$dep,$workflow,'Preserved branding task');$sub=$this->postJson('/pms/api/subtasks',['task_id'=>$task,'title'=>'Logo checklist'])->assertOk();$subId=DB::table('pms_subtasks')->where('task_id',$task)->value('id');$this->postJson('/pms/api/tasks/'.$task.'/comments',['body'=>'Keep this design feedback'])->assertCreated();DB::table('pms_task_attachments')->insert(['task_id'=>$task,'original_name'=>'brand-guide.txt','path'=>'audit/brand-guide.txt','mime_type'=>'text/plain','size'=>20,'created_at'=>now(),'updated_at'=>now()]);$worker=$this->user($platform,$dep,'developer',['project-view']);$log=DB::table('pms_timer_logs')->insertGetId(['user_id'=>$worker->id,'task_id'=>$task,'start_time'=>now()->subHour(),'end_time'=>now()->subMinutes(30),'created_at'=>now(),'updated_at'=>now()]);
  $old=$this->user($platform,$dep,'developer',['project-view']);$shared=$this->user($platform,$dep,'developer',['project-view']);DB::table('communication_company_memberships')->insert(['company_id'=>$targetPlatform,'user_id'=>$shared->id]);foreach([$old,$shared] as $u){DB::table('pms_task_user')->insert(['task_id'=>$task,'user_id'=>$u->id]);DB::table('pms_subtask_user')->insert(['subtask_id'=>$subId,'user_id'=>$u->id]);}
  $manager=$this->user($platform,$dep,'project_manager',['project-view','project-view-all','task-edit','report-view']);$this->withSession(['judibas_admin'=>false])->actingAs($manager);$this->getJson('/pms/api/projects/'.$destination)->assertOk();$body=['project_id'=>$destination,'department_id'=>$dep,'reason'=>'Move delivery to Summit'];$this->postJson('/pms/api/tasks/'.$task.'/transfer',$body)->assertForbidden();$this->getJson('/pms/api/tasks/'.$task.'/transfer')->assertForbidden();$this->grant($manager,'task-transfer-company');$this->getJson('/pms/api/tasks/'.$task.'/transfer')->assertOk();$this->postJson('/pms/api/tasks/'.$task.'/transfer',$body)->assertOk();
  $this->assertDatabaseHas('pms_tasks',['id'=>$task,'project_id'=>$destination,'department_id'=>$dep,'workflow_id'=>$targetWorkflow,'status'=>'pending']);$this->assertDatabaseHas('pms_task_comments',['task_id'=>$task,'body'=>'Keep this design feedback']);$this->assertDatabaseHas('pms_task_attachments',['task_id'=>$task,'original_name'=>'brand-guide.txt']);$this->assertDatabaseHas('pms_timer_logs',['id'=>$log,'task_id'=>$task]);$this->assertDatabaseHas('pms_subtasks',['id'=>$subId,'task_id'=>$task]);$this->assertDatabaseMissing('pms_task_user',['task_id'=>$task,'user_id'=>$old->id]);$this->assertDatabaseMissing('pms_subtask_user',['subtask_id'=>$subId,'user_id'=>$old->id]);$this->assertDatabaseHas('pms_task_user',['task_id'=>$task,'user_id'=>$shared->id]);$this->assertDatabaseHas('pms_subtask_user',['subtask_id'=>$subId,'user_id'=>$shared->id]);$this->assertDatabaseHas('pms_task_transfers',['task_id'=>$task,'user_id'=>$manager->id,'reason'=>'Move delivery to Summit']);
  $this->getJson('/pms/api/reports/data?client_id='.$targetClient)->assertOk()->assertJsonFragment(['title'=>'Preserved branding task']);$this->getJson('/pms/api/reports/data?client_id='.$client)->assertOk()->assertJsonMissing(['title'=>'Preserved branding task']);$this->actingAs($old)->getJson('/pms/api/tasks/'.$task)->assertNotFound();$this->actingAs($shared)->getJson('/pms/api/tasks/'.$task)->assertOk();
 }
 public function test_transfer_rejects_running_timers_and_invalid_destination_without_partial_changes():void {
  [$platform, $company]=$this->company('Audit Bluebird');[, $targetCompany]=$this->company('Audit Evergreen');$dep=$this->department('Audit Marketing');$wrong=$this->department('Audit Wrong Department');[$project,,$workflow]=$this->project($company,'Audit Bluebird Campaign',[$dep]);[$destination,,$targetWorkflow]=$this->project($targetCompany,'Audit Evergreen Campaign',[$dep]);$task=$this->task($project,$dep,$workflow,'Campaign plan');$body=['project_id'=>$destination,'department_id'=>$dep];$this->postJson('/pms/api/tasks/'.$task.'/transfer',array_replace($body,['department_id'=>$wrong]))->assertUnprocessable();$worker=$this->user($platform,$dep,'developer',['project-view']);$timer=DB::table('pms_timer_logs')->insertGetId(['user_id'=>$worker->id,'task_id'=>$task,'start_time'=>now(),'end_time'=>null,'created_at'=>now(),'updated_at'=>now()]);$this->postJson('/pms/api/tasks/'.$task.'/transfer',$body)->assertUnprocessable();$this->assertDatabaseHas('pms_tasks',['id'=>$task,'project_id'=>$project,'workflow_id'=>$workflow]);$this->assertDatabaseMissing('pms_task_transfers',['task_id'=>$task]);DB::table('pms_timer_logs')->where('id',$timer)->update(['end_time'=>now()]);$this->postJson('/pms/api/tasks/'.$task.'/transfer',$body)->assertOk();
 }
}
